create table FM_DATE (HALF_END_DATE TIMESTAMP(3) not null  ,QUR_END_DATE TIMESTAMP(3) not null  ,ACCT_EOD_FLAG VARCHAR(20) not null  ,MTH_END_DATE TIMESTAMP(3) not null  ,NEXT_RUN_DATE TIMESTAMP(3) not null  ,COMPANY VARCHAR(20) not null  ,LAST_RUN_DATE TIMESTAMP(3) not null  ,LAST_UPD_TIMESTAMP VARCHAR(26) not null  ,RUN_DATE TIMESTAMP(3) not null  ,CREATE_TIMESTAMP VARCHAR(26) not null  ,YR_END_DATE TIMESTAMP(3) not null  ,SUSPEND_FLAG VARCHAR(1) null  ,SYSTEM_PHASE VARCHAR(10) not null  , primary key(COMPANY));